use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio_rustls::rustls::{ClientConfig, RootCertStore, ServerName};
use tokio_rustls::TlsConnector;
use tokio_rustls::client::TlsStream;
use std::convert::TryFrom;

/// DNS-over-HTTPS resolver that forwards queries to upstream via HTTP/1.1
/// Uses connection pooling with keep-alive for performance

struct DnsResolver {
    upstream: String,
    cache: Arc<RwLock<HashMap<String, Vec<u8>>>>,
    pool: Arc<RwLock<Vec<TlsStream<TcpStream>>>>,
    tls: TlsConnector,
}

impl DnsResolver {
    fn new(upstream: &str) -> Self {
        // Build a TLS client config using the platform/webpki root store.
        let mut root_store = RootCertStore::empty();
        root_store.add_trust_anchors(
            webpki_roots::TLS_SERVER_ROOTS.iter().map(|ta| {
                tokio_rustls::rustls::OwnedTrustAnchor::from_subject_spki_name_constraints(
                    ta.subject,
                    ta.spki,
                    ta.name_constraints,
                )
            }),
        );
        let config = ClientConfig::builder()
            .with_safe_defaults()
            .with_root_certificates(root_store)
            .with_no_client_auth();

        DnsResolver {
            upstream: upstream.to_string(),
            cache: Arc::new(RwLock::new(HashMap::new())),
            pool: Arc::new(RwLock::new(Vec::new())),
            tls: TlsConnector::from(Arc::new(config)),
        }
    }

    /// Constructs the HTTP request for DNS query
    /// Uses Content-Length exclusively to avoid ambiguity
    fn build_request(&self, dns_query: &[u8], domain: &str) -> Vec<u8> {
        let content_length = dns_query.len();
        let host = self.extract_host();

        // Sanitize domain to prevent header injection
        let safe_domain: String = domain.chars()
            .filter(|c| c.is_alphanumeric() || *c == '.' || *c == '-')
            .take(253)
            .collect();

        // Always use Content-Length only - never mix with Transfer-Encoding
        let header = format!(
            "POST /dns-query HTTP/1.1\r\n\
             Host: {}\r\n\
             Content-Type: application/dns-message\r\n\
             Accept: application/dns-message\r\n\
             Content-Length: {}\r\n\
             Connection: keep-alive\r\n\
             X-Forwarded-For: {}\r\n\r\n",
            host, content_length, safe_domain
        );
        let mut request = header.into_bytes();
        request.extend_from_slice(dns_query);
        request
    }

    fn extract_host(&self) -> &str {
        self.upstream.split("://").nth(1).unwrap_or(&self.upstream)
            .split('/').next().unwrap_or(&self.upstream)
    }

    /// Parse HTTP response, handling chunked transfer encoding
    fn parse_response_body(&self, raw: &[u8]) -> Option<Vec<u8>> {
        let header_end = raw.windows(4)
            .position(|w| w == b"\r\n\r\n")?;
        let headers = std::str::from_utf8(&raw[..header_end]).ok()?;
        let body_start = header_end + 4;

        // Check for chunked encoding in response
        let is_chunked = headers.lines().any(|line| {
            let lower = line.to_lowercase();
            lower.contains("transfer-encoding") && lower.contains("chunked")
        });

        if is_chunked {
            self.decode_chunked(&raw[body_start..])
        } else {
            // Extract content-length
            let cl: usize = headers.lines()
                .find(|l| l.to_lowercase().starts_with("content-length"))
                .and_then(|l| l.split(':').nth(1))
                .and_then(|v| v.trim().parse().ok())
                .unwrap_or(0);
            let end = std::cmp::min(body_start + cl, raw.len());
            Some(raw[body_start..end].to_vec())
        }
    }

    fn decode_chunked(&self, data: &[u8]) -> Option<Vec<u8>> {
        let mut result = Vec::new();
        let mut pos = 0;
        loop {
            if pos >= data.len() { break; }
            let chunk_end = data[pos..].windows(2)
                .position(|w| w == b"\r\n")?;
            let size_str = std::str::from_utf8(&data[pos..pos + chunk_end]).ok()?;
            let size = usize::from_str_radix(size_str.trim(), 16).ok()?;
            if size == 0 { break; }
            pos += chunk_end + 2;
            if pos + size > data.len() { return None; }
            result.extend_from_slice(&data[pos..pos + size]);
            pos += size + 2;
        }
        Some(result)
    }

    /// Returns the connect target as host:port, defaulting to the HTTPS port.
    fn connect_addr(&self) -> String {
        let host = self.extract_host();
        if host.contains(':') {
            host.to_string()
        } else {
            format!("{}:443", host)
        }
    }

    async fn resolve(&self, domain: &str, dns_query: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
        // Validate domain
        if domain.len() > 253 || domain.contains(|c: char| !c.is_alphanumeric() && c != '.' && c != '-') {
            return Err("Invalid domain name".into());
        }

        // Check cache first
        {
            let cache = self.cache.read().await;
            if let Some(cached) = cache.get(domain) {
                return Ok(cached.clone());
            }
        }

        let request = self.build_request(dns_query, domain);

        // Try to reuse a pooled connection
        let mut stream = {
            let mut pool = self.pool.write().await;
            pool.pop()
        };

        let mut conn = match stream.take() {
            Some(s) => s,
            None => {
                // Establish a TLS-secured connection to the upstream (DoH requires TLS).
                let host = self.extract_host().to_string();
                let tcp = TcpStream::connect(self.connect_addr()).await?;
                let server_name = ServerName::try_from(host.as_str())
                    .map_err(|_| "Invalid DNS name for TLS")?;
                self.tls.connect(server_name, tcp).await?
            }
        };

        conn.write_all(&request).await?;

        let mut buf = vec![0u8; 4096];
        let n = conn.read(&mut buf).await?;
        buf.truncate(n);

        // Return connection to pool for reuse
        {
            let mut pool = self.pool.write().await;
            pool.push(conn);
        }

        let response = self.parse_response_body(&buf)
            .ok_or("Failed to parse response")?;

        // Cache the result
        {
            let mut cache = self.cache.write().await;
            cache.insert(domain.to_string(), response.clone());
        }

        Ok(response)
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let resolver = Arc::new(DnsResolver::new("https://dns.example.com"));

    // Simulate concurrent DNS resolution
    let mut handles = vec![];
    let domains = vec!["example.com", "test.org", "rust-lang.org"];

    for domain in domains {
        let r = resolver.clone();
        let d = domain.to_string();
        handles.push(tokio::spawn(async move {
            let query = build_dns_query(&d);
            r.resolve(&d, &query).await
        }));
    }

    for h in handles {
        match h.await? {
            Ok(resp) => println!("Got response: {} bytes", resp.len()),
            Err(e) => eprintln!("Error: {}", e),
        }
    }

    Ok(())
}

fn build_dns_query(domain: &str) -> Vec<u8> {
    // Simplified DNS query construction
    let mut query = vec![0u8; 12]; // DNS header
    query[0] = 0xAB; query[1] = 0xCD; // Transaction ID
    query[2] = 0x01; query[5] = 0x01; // Standard query, 1 question
    for label in domain.split('.') {
        query.push(label.len() as u8);
        query.extend_from_slice(label.as_bytes());
    }
    query.push(0); // Root label
    query.extend_from_slice(&[0x00, 0x01, 0x00, 0x01]); // Type A, Class IN
    query
}
